mapper.update:
UPDATE improvement_proposal
SET status      = #{status},
    attribution = #{attribution}
WHERE id = #{id}

UPDATE improvement_proposal
SET status      = #{status},
    review_note = #{reviewNote}
WHERE id = #{id}

mapper.select:
SELECT id, source_kind AS sourceKind, problem_card AS problemCard, target, status, attribution, dedup_key AS dedupKey, review_note AS reviewNote, created_at AS createdAt, updated_at AS updatedAt FROM improvement_proposal
AND status = #{status}
ORDER BY id DESC LIMIT #{size} OFFSET #{offset}
